  | LPAR  -> 1 
  | RPAR  -> 2 
  | PLUS  -> 3 
  | EQ  -> 4 
  | MINUS  -> 5 
  | TIMES  -> 6 
  | VAR _ -> 7 
  | INT _ -> 8 

